-- =============================================================================
-- Dummy catalog data for local UI testing — 10 books, 3 authors, 2 publishers.
-- Distinct, hand-written content per book (not repeated placeholder text) so
-- descriptions/summaries/key takeaways/related-books all look realistic.
--
-- LOCAL ONLY. This is fake data for local dev — never run with --remote.
-- Production already has its own real catalog (~thousands of rows); running
-- this against production would pollute it with test books.
--
-- Run AFTER catalog_schema.sql:
--   npx wrangler d1 execute catalog --local --file=sql/catalog_schema.sql
--   npx wrangler d1 execute catalog --local --file=sql/catalog_seed.sql
-- =============================================================================

DELETE FROM books;
DELETE FROM authors;
DELETE FROM catalog_counts WHERE id=1;
